	if err != nil || !item.Enabled {
		writeError(w, http.StatusServiceUnavailable, "provider_unavailable", "선택한 AI 공급자를 사용할 수 없습니다.")
		return
	}
	if _, ok := payload["model"]; !ok {
		payload["model"] = item.DefaultModel
	}
	model, modelOK := payload["model"].(string)
	model = strings.TrimSpace(model)
	if !modelOK || model == "" || utf8.RuneCountInString(model) > 240 {
		writeError(w, http.StatusBadRequest, "model_invalid", "사용할 모델 이름이 올바르지 않습니다.")
		return
