// auditResourceIDMaximum matches ai_admin.audit_event.resource_id (varchar(500)).
const auditResourceIDMaximum = 500

// storableResourceID keeps the audited resource identifier short enough to be
// stored. Some callers audit a value that reached the server before any
// validation could bound it — a failed login records the submitted username,
// which has no length limit of its own — and an over-long value makes the audit
// INSERT fail. That either drops the record silently (audit) or fails the
// surrounding mutation (auditInTx), so both paths bound the value the same way
// rather than letting the caller decide whether its event is recorded.
func storableResourceID(value string) string {
	return truncateRunes(value, auditResourceIDMaximum)
}

func (s *Server) audit(r *http.Request, p auth.Principal, action, resourceType, resourceID, result string, details any) {
	if details == nil {
