		return
	}
	if request.Name != nil {
		// ai_admin.role.name is varchar(120); a longer value used to reach the
		// column and come back as a 500. The limit counts characters like the
		// user display name check because role names are entered in Korean.
		// varchar cannot hold a NUL at any length either, so it is refused in
		// the same place with the same 400.
		value := strings.TrimSpace(*request.Name)
		if value == "" || utf8.RuneCountInString(value) > 120 || !storableInVarchar(value) {
			writeError(w, 400, "name_invalid", "역할 이름이 올바르지 않습니다.")
