// locale·timezone은 varchar(20)·varchar(80) column에 그대로 들어간다. 상한을 넘는
// 값이나 형식에 맞지 않는 값을 그대로 upsert하면 DB가 거부해 400이어야 할 요청이
// 500 preferences_update_failed가 되고, 같은 요청에 담긴 다른 설정 변경까지 함께
// 사라진다. 저장할 수 있는 형식만 받아 저장소가 아니라 요청을 탓하게 한다.
var (
	preferenceLocalePattern   = regexp.MustCompile(`^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$`)
	preferenceTimezonePattern = regexp.MustCompile(`^[A-Za-z0-9._+-]+(/[A-Za-z0-9._+-]+)*$`)
)

func validPreferenceLocale(value string) bool {
	return utf8.RuneCountInString(value) <= 20 && preferenceLocalePattern.MatchString(value)
}

func validPreferenceTimezone(value string) bool {
	return utf8.RuneCountInString(value) <= 80 && preferenceTimezonePattern.MatchString(value)
}

func optionalTrimmed(value *string) string {
	if value == nil {
		return ""
	}
	return strings.TrimSpace(*value)
}

type userPreferences struct {
	theme         string
	locale        string
	timezone      string
	fontScale     float64
	sidebar       []byte
	aiDefaults    []byte
	notifications []byte
}

func defaultPreferences() userPreferences {
	return userPreferences{
		theme: "system", locale: "ko-KR", timezone: "Asia/Seoul", fontScale: 1,
		sidebar: []byte(`{}`), aiDefaults: []byte(`{}`), notifications: []byte(`{"email":true,"approval":true}`),
	}
}

// loadPreferences reads the stored settings of one account. A missing row means
// the account has never saved anything, which is the column defaults rather
// than a failure; only a query error is reported as one.
func (s *Server) loadPreferences(ctx context.Context, userID uuid.UUID) (userPreferences, error) {
	current := defaultPreferences()
	err := s.db.Pool.QueryRow(ctx, `SELECT theme,locale,timezone,font_scale::float8,sidebar_state,ai_defaults,notification_preferences FROM ai_admin.user_preference WHERE user_id=$1`, userID).Scan(
		&current.theme, &current.locale, &current.timezone, &current.fontScale, &current.sidebar, &current.aiDefaults, &current.notifications)
	if errors.Is(err, pgx.ErrNoRows) {
		return defaultPreferences(), nil
	}
	if err != nil {
		return userPreferences{}, err
	}
	return current, nil
}

